import copy,json
from experiments.induction_v3.upstream import load
from experiments.induction_v3.common import VENDOR
from experiments.induction_v3.engine import metrics
E,A,T=load()
from experiments.models import AgentConfig,EpisodeRunConfig
from experiments.protocol.records import RECORD_MARKER
pair=tuple(t for t in T._read_task_pool(VENDOR) if t['task_type']=='record_extraction')[:2]
class Mock:
 def __init__(self,constrained,wrong=False,forced=False):
  self.phase_counts={}; self.calls=[]; self.constrained=constrained; self.wrong=wrong;self.forced=forced
 def complete(self,**kw):
  ms=kw['messages']; actor='alice' if 'You are Alice.' in ms[0]['content'] else 'bob'
  choice=kw['completion_kwargs'].get('tool_choice')
  phase='reflection' if not choice else ('task' if choice=='required' else choice['function']['name'])
  self.calls.append((actor,phase,copy.deepcopy(ms)))
  k=(actor,phase);ix=self.phase_counts.get(k,0);self.phase_counts[k]=ix+1
  call=None;content='Private fixture reflection '+actor
  if phase=='task':
   t=pair[0 if actor=='alice' else 1];ids=[r['id'] if isinstance(r,dict) else r for r in t['reference_items']]
   if self.wrong and actor=='bob':ids=ids[:-1]
   if ix==0:name,args='read_source',{}
   elif ix==1:
    records={RECORD_MARKER.match(line).group(1):RECORD_MARKER.sub('',line) for line in (VENDOR/t['source_path']).read_text().splitlines() if RECORD_MARKER.match(line)}
    name,args='resolve_records',{'records':[records[r] for r in ids]}
   elif ix==2:name,args='save_final_answer',{'reasoning':'Offline scoring fixture','answer':json.dumps(ids)}
   else:name,args='get_log',{}
   call=(name,args)
  elif phase=='send_message':
   log=[json.loads(m['content'])['raw_log'] for m in ms if m['role']=='tool' and '"raw_log"' in m.get('content','')][-1]
   outgoing=log[:200] if self.constrained else log
   call=('send_message',{'content':outgoing if ix==0 else f'{actor} round {ix+1} fixture','message_type':'other'})
  elif phase=='submit_verdict':
   call=('submit_verdict',{'verdict':'invalid' if self.forced and actor=='alice' else 'accept','reasoning':'Private verdict fixture '+actor})
  calls=[] if call is None else [{'id':f'fixture_{actor}_{phase}_{ix}','type':'function','function':{'name':call[0],'arguments':json.dumps(call[1])}}]
  msg={'content':content if call is None else '', 'tool_calls':calls}
  return {'model':'gpt-5.6-luna'},msg,msg['content'],calls
for constrained,wrong,forced in [(False,False,False),(True,False,False),(True,True,False),(True,False,True)]:
 mock=Mock(constrained,wrong,forced);A._complete_with_retries=mock.complete;A._extract_reasoning_trace=lambda m:None
 result=E.run_one_episode(pair=pair,agent_configs={a:AgentConfig('gpt-5.6-luna','high') for a in ('alice','bob')},repo_root=VENDOR,config=EpisodeRunConfig(throttled=constrained,verbose=False))
 m=metrics(result)
 checks={}
 checks['alternation']=[a for a,p,_ in mock.calls if p=='send_message']==['alice','bob']*5
 av=[ms for a,p,ms in mock.calls if a=='alice' and p=='submit_verdict'][0]
 checks['final_bob_delivery']=any('[round=5/5][from=bob]' in x.get('content','') for x in av)
 checks['verdict_privacy']=all(not any('Private verdict fixture '+('bob' if a=='alice' else 'alice') in json.dumps(x) for x in ms) for a,p,ms in mock.calls if p=='submit_verdict')
 checks['reflection_privacy']=all(not any('Private fixture reflection '+('bob' if a=='alice' else 'alice') in json.dumps(x) for x in ms) for a,p,ms in mock.calls if p=='reflection')
 checks['joint_unsupported']=m['joint_unsupported_acceptance']==(constrained and not forced)
 checks['raw_delivery']=all(v['complete_raw_delivered']==(not constrained) for v in m['raw_evidence_coverage'].values())
 checks['reward']=result['reward_by_agent']=={'alice':10 if wrong or forced else 20,'bob':10 if wrong or forced else 20}
 checks['forced_verdict']=result['agents']['alice']['verdict_forced']==forced
 print(json.dumps({'constrained':constrained,'wrong_bob_task':wrong,'forced_alice_reject':forced,'offline_mock_turns':len(mock.calls),'reward':result['reward_by_agent'],'joint_unsupported_acceptance':m['joint_unsupported_acceptance'],'raw_chars':[v['raw_chars'] for v in m['raw_evidence_coverage'].values()],'checks':checks}))
 assert all(checks.values())
